import{z as s,x as i,o as B,c as g,q as r,j as n,D as e,d as a,s as l,S as o,b as t}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"多 Agent 编排模式","description":"","frontmatter":{"title":"多 Agent 编排模式","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/agent-multi-orchestration.md","filePath":"llm/agent-multi-orchestration.md","lastUpdated":1791413859000}'),m={name:"llm/agent-multi-orchestration.md"};function d(p,E,h,C,D,c){const A=i("Mermaid");return B(),g("div",null,[E[2]||(E[2]=r('<h1 id="多-agent-编排模式" tabindex="-1">多 Agent 编排模式 <a class="header-anchor" href="#多-agent-编排模式" aria-label="Permalink to &quot;多 Agent 编排模式&quot;">​</a></h1><div class="epigraph"><p>多代理不是能力相加，是把上下文、权限和失败半径切开；切错了方向，得到的是几份账单和一个更难调试的系统。</p><footer>—— 据 Wang 等，大模型自主代理综述，2024；以及多代理框架的公开工程口径整理</footer></div><p><a href="/llm/agent-memory-implementation">上一课</a>把记忆外置之后，单环的最后一块短板也显形了：所有职责共用一个上下文、一套权限、一个失败半径。编排把控制流劈开。主干已有<a href="/llm/multi-agent-orchestration">多代理编排</a>讲框架谱系（CAMEL、MetaGPT、AutoGen 的对话与 SOP 模式）；本课把编排当<strong>生产决策</strong>来写：什么时候值得拆、按什么切、拆完付什么税。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>拆分的收益有四项，对应四种痛：<strong>上下文隔离</strong>——子代理各带干净窗口，探索性阅读的噪声不回流主轨迹（机制见<a href="/llm/multi-agent-context-isolation">多智能体上下文隔离</a>）；<strong>权限隔离</strong>——只有执行者握写权限，评审者只读，注入的损失上限随权限收窄；<strong>并行</strong>——读侧任务（多文件调研、多方案试写）天然可并行；<strong>独立验证</strong>——评审代理看不见作者的推理过程，锚定被切断。对应的税也有四项：<strong>通信有损</strong>——编排者只见子代理的报告，报告没写的细节对主代理不存在；<strong>费用倍增</strong>——每个子代理重付系统提示与任务简报；<strong>一致性</strong>——两个代理并发改同一文件，锁与合并要做；<strong>终止</strong>——互相等待或互相推诿的代理环需要超时与仲裁。拆错方向的典型：把强耦合的读写任务拆给两个并行代理，全部预算花在互相修复上。<span class="marginnote">失败半径是工程术语：一个组件出事时能波及的最大范围。单代理里，一次误操作的写权限、一段被注入的指令、一个塞爆的上下文全在同一半径内；拆分后评审代理只读、执行者只拿子集工具，等于给可能的事故画了隔离墙。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按信息流与权限流选模式。<strong>流水线</strong>：阶段工件交接，上游不见下游反馈，适合稳定 SOP；换任务域要重写流程。<strong>编排者—工人</strong>：主代理动态拆子任务、给每个子代理一份任务简报与工具子集，只收结构化报告；<a href="/llm/claude-agent-sdk">Claude Agent SDK</a> 与 <a href="/llm/agentloop-server">server-based AgentLoop</a> 把这做成一等原语，报告模板（结论、证据、不确定度、改动清单）是编排质量的第一瓶颈。<strong>评审/辩论</strong>：独立上下文的批评者对产出复核，何时反驳有价值见<a href="/llm/debate-oversight">辩论</a>；注意评审者与作者同源时的<a href="/llm/self-preference-bias">自我偏好</a>。<strong>群聊/共享黑板</strong>：全员可见全部消息，调试直观，费用随人数平方涨，适合少量角色短程协作。<span class="marginnote">「平方」的数字实例：n 个角色互相都可能说话，通道数约 n×(n−1) 条——4 个角色 12 条，8 个角色 56 条。人数翻倍，消息量约翻四倍，还都要过模型理解一遍，所以群聊模式角色一多，账单先爆炸。</span>跨组织边界、互不信任的代理之间，工具协议要换成服务协议（<a href="/llm/a2a-protocol">A2A 协议</a>），那是信任模型不同，不是同一模式的远距离版。</p>',7)),(B(),n(o,null,{default:e(()=>[l(A,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E4%BB%BB%E5%8A%A1%E8%BF%9B%E5%85%A5%E7%BC%96%E6%8E%92%E8%80%85%22%5D%20--%3E%20DEC%7B%22%E8%80%A6%E5%90%88%E5%BA%A6%E4%B8%8E%E6%9D%83%E9%99%90%E9%9C%80%E6%B1%82%22%7D%0A%20%20DEC%20--%3E%7C%22%E7%BA%BF%E6%80%A7%E3%80%81SOP%20%E7%A8%B3%E5%AE%9A%22%7C%20PIPE%5B%22%E6%B5%81%E6%B0%B4%E7%BA%BF%EF%BC%9A%E9%98%B6%E6%AE%B5%E5%B7%A5%E4%BB%B6%E4%BA%A4%E6%8E%A5%22%5D%0A%20%20DEC%20--%3E%7C%22%E5%8F%AF%E6%8B%86%E3%80%81%E9%9C%80%E9%9A%94%E7%A6%BB%22%7C%20ORCH%5B%22%E7%BC%96%E6%8E%92%E8%80%85-%E5%B7%A5%E4%BA%BA%EF%BC%9A%E5%AD%90%E4%BB%A3%E7%90%86%E5%B8%A6%E5%B7%A5%E5%85%B7%E5%AD%90%E9%9B%86%22%5D%0A%20%20DEC%20--%3E%7C%22%E9%9C%80%E7%8B%AC%E7%AB%8B%E5%A4%8D%E6%A0%B8%22%7C%20REV%5B%22%E8%AF%84%E5%AE%A1%2F%E8%BE%A9%E8%AE%BA%EF%BC%9A%E7%8B%AC%E7%AB%8B%E4%B8%8A%E4%B8%8B%E6%96%87%22%5D%0A%20%20DEC%20--%3E%7C%22%E5%B0%91%E9%87%8F%E8%A7%92%E8%89%B2%E3%80%81%E7%9F%AD%E7%A8%8B%22%7C%20GROUP%5B%22%E7%BE%A4%E8%81%8A%EF%BC%9A%E5%85%B1%E4%BA%AB%E9%BB%91%E6%9D%BF%22%5D%0A%20%20ORCH%20--%3E%20RPT%5B%22%E7%BB%93%E6%9E%84%E5%8C%96%E6%8A%A5%E5%91%8A%E5%9B%9E%E4%BC%A0%22%5D%0A%20%20RPT%20--%3E%20MERGE%5B%22%E5%90%88%E5%B9%B6%E4%B8%8E%E5%86%B2%E7%AA%81%E6%A3%80%E6%9F%A5%22%5D%0A%20%20PIPE%20--%3E%20MERGE%0A%20%20REV%20--%3E%20MERGE%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t("h2",{id:"机制",tabindex:"-1"},[a("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=t("p",null,[a("编排提升质量的机制是隔离与独立，不是人数：评审代理有用，是因为它没有作者的沉没成本与自我辩护链；子代理有用，是因为它的窗口不背主轨迹的历史。同一机制决定失败面：隔离切断的不只是噪声，还有上下文——子代理不知道主代理已知的约束，简报漏写就是行为差异。所以简报与报告模板要当接口协议管理（回指"),t("a",{href:"/llm/agent-tool-protocol-deep"},"工具协议深钻"),a("的 schema 纪律）：写明输入假设、输出结构、权限边界。一致性的机制解是所有权：同一时刻一个文件只归一个代理写，其余排队或申请，锁比事后合并便宜。")],-1)),(B(),n(o,null,{default:e(()=>[l(A,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E4%B8%BB%E4%BB%A3%E7%90%86%E4%B8%8A%E4%B8%8B%E6%96%87%EF%BC%9A%E7%9B%AE%E6%A0%87%E3%80%81%E7%BA%A6%E6%9D%9F%E3%80%81%E5%8E%86%E5%8F%B2%E8%BD%A8%E8%BF%B9%22%5D%20--%3E%20B%5B%22%E4%BB%BB%E5%8A%A1%E7%AE%80%E6%8A%A5%EF%BC%9A%E5%86%99%E4%B8%8B%E6%9D%A5%E7%9A%84%E9%83%A8%E5%88%86%22%5D%0A%20%20M%20-.%20%22%E6%B2%A1%E5%86%99%E8%BF%9B%E7%AE%80%E6%8A%A5%E7%9A%84%E9%9A%90%E6%80%A7%E7%BA%A6%E6%9D%9F%22%20.-%3E%20X%5B%22%E5%AF%B9%E5%AD%90%E4%BB%A3%E7%90%86%E4%B8%8D%E5%AD%98%E5%9C%A8%22%5D%0A%20%20B%20--%3E%20S%5B%22%E5%AD%90%E4%BB%A3%E7%90%86%EF%BC%9A%E5%B9%B2%E5%87%80%E7%AA%97%E5%8F%A3%20%2B%20%E5%B7%A5%E5%85%B7%E5%AD%90%E9%9B%86%22%5D%0A%20%20S%20--%3E%20R%5B%22%E7%BB%93%E6%9E%84%E5%8C%96%E6%8A%A5%E5%91%8A%22%5D%0A%20%20R%20--%3E%20M%0A%20%20X%20-.-%3E%20D%5B%22%E8%A1%8C%E4%B8%BA%E5%B7%AE%E5%BC%82%E4%B8%8E%E8%BF%94%E5%B7%A5%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p><span class="marginnote">可以把它想象成给外包团队写需求文档：文档里没写的需求对方就真的不知道，做偏了不能全怪外包。初学者容易以为子代理「不听话」，实际上简报漏写约束导致的偏差，责任在接口协议这一层，补简报比换模型有效。</span></p><p><span class="marginnote">一得一失常被一起忽略：并行子代理把墙钟时间缩短，但每个子代理都要重付系统提示与工具说明——并行省时间不省钱；预算紧的任务，串行加缓存反而更便宜。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>任务可线性分解、上下文装得下时，单代理加好工具总是更便宜的选择：编排是给「装不下或权限必须分」的任务付的税。编排器本身也会成为单点：它选错模式、简报写偏，下游全错——编排者的决策要进轨迹（<a href="/llm/agent-observability">可观测性</a>）才能复盘。编排的失败恢复不在本课：某条子环死了怎么办，是<a href="/llm/agent-error-recovery">错误恢复与重试</a>的分级问题在多代理下的实例。把「多代理」当评测加分项是方向性错误：评测只认任务成败与过程（<a href="/llm/agent-eval-success-process">评测：任务成功率与过程</a>），不认架构名头。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>拆分买四样：上下文隔离、权限隔离、并行、独立验证；付四税：通信有损、费用、一致性、终止。</li><li>编排者—工人是默认模式；简报与报告模板是接口协议，要按 schema 纪律管理。</li><li>群聊费用随人数平方涨；评审要防同源自我偏好。</li><li>一致性靠所有权与锁，不靠事后合并。</li><li>单代理够用时不要编排：编排是税，不是荣誉。</li><li>出处：据 Wang 等（2024）综述与主流多代理框架的公开口径整理。</li></ul>',6))])}const F=s(m,[["render",d]]);export{u as __pageData,F as default};
